"""Native separator boundary for two complete, explicitly free approaches.

Recover existing inner sides and the attached patch chain by exact ownership
and mouth identities. The open end gets a new straight cap between the two
actual inner end corners. Only that cap's interior vertices are new; they are
included in the working reference so the existing quad fill can prove every
boundary coordinate and weld by identity. No replacement road edges are fit.
"""
import bpy
from . import curved_separator_boundary_nodes as closed
from . import curved_junction_nodes as boundary
from . import curved_patch_provider_nodes as providers

c = closed.c
NAME = 'Prochitecture Streets / Free-ended separator boundary v1'
MAX_CAP_INTERVALS = 4096


def _simple_footprint(g, reference, *parts):
    """Check every boundary edge, including the newly constructed free cap.

    Joining by exact original IDs makes a topological loop. Mesh to Curve on
    this degree-two wire supplies its order; EVALUATED points of that polygon
    retain every original vertex. The bounded complete contact checker then
    rejects nonneighbor crossings, touching and collinear overlaps.
    """
    from .path_surface_nodes import _Nodes
    from . import blocked_boundary_nodes
    native = _Nodes(g.g)
    loop = boundary._join(g, *parts)
    identity = c.named(g, 'st_sb_original_vertex', 'INT')
    encoded = g.setpos(loop, g.xyz(identity))
    merge = g.node('GeometryNodeMergeByDistance', 'Join four chains by exact vertex identity')
    merge.inputs['Distance'].default_value = .1
    g.bind(encoded, merge.inputs['Geometry'])
    loop = g.setpos(merge.outputs['Geometry'], c._sample(g, reference, g.position(), identity, 'FLOAT_VECTOR'))
    degree = g.node('GeometryNodeInputMeshVertexNeighbors').outputs['Vertex Count']
    islands = g.node('GeometryNodeInputMeshIsland').outputs['Island Count']
    expected = sum(c._count(g, part) for part in parts)-4.
    topology = (g.math('COMPARE', c._count(g, loop), expected)*
                c._stat(g, loop, g.math('COMPARE', degree, 2.))*
                g.math('COMPARE', c._stat(g, loop, islands, 'Max'), 1.))
    curve = g.node('GeometryNodeMeshToCurve', 'Order the complete polygonal separator boundary')
    g.bind(loop, curve.inputs['Mesh'])
    points = g.node('GeometryNodeCurveToPoints', 'Keep every original polyline vertex'); points.mode = 'EVALUATED'
    g.bind(curve.outputs['Curve'], points.inputs['Curve'])
    vertices = g.node('GeometryNodePointsToVertices', 'Ordered complete boundary for contact checking')
    g.bind(points.outputs['Points'], vertices.inputs['Points'])
    ordered = vertices.outputs['Mesh']
    count = c._count(g, ordered)
    index = g.node('GeometryNodeInputIndex').outputs[0]
    pos = g.node('GeometryNodeInputPosition').outputs[0]
    clear = blocked_boundary_nodes.check(native, ordered, count.s, index, pos, 1e-6)
    return topology*g.math('COMPARE', count, expected)*c.V(g, clear)


def _chain_valid(g, geometry):
    neighbor = g.node('GeometryNodeInputMeshVertexNeighbors').outputs['Vertex Count']
    island = g.node('GeometryNodeInputMeshIsland').outputs['Island Count']
    end = g.math('COMPARE', neighbor, 1.)
    degree = g.math('MAXIMUM', end, g.math('COMPARE', neighbor, 2.))
    return (g.math('GREATER_THAN', c._count(g, geometry), 1.5)*
            g.math('COMPARE', c._stat(g, geometry, island, 'Max'), 1.)*
            c._stat(g, geometry, degree)*g.math('COMPARE', c._stat(g, geometry, end, 'Sum'), 2.))


def _permissions(g, geometry):
    """Small private owner rows for the two sides and the attached cap."""
    from . import curved_network_ownership_nodes as ownership
    role, kind, owner = (c.named(g, 'st_sr_'+key, 'INT') for key in ('role', 'kind', 'owner'))
    valid = c._stat(g, geometry, ownership._exists(g, ('st_sr_role', 'st_sr_kind', 'st_sr_owner')))
    valid = valid*g.math('GREATER_THAN', c._count(g, geometry), .5)*g.math('LESS_THAN', c._count(g, geometry), 512.5)
    fields = ((1.-g.math('LESS_THAN', role, 0.))*g.math('LESS_THAN', role, 3.)*
              (g.math('COMPARE', kind, 0.)+g.math('COMPARE', kind, 1.)+g.math('COMPARE', kind, 3.))*
              (1.-g.math('LESS_THAN', owner, 0.))*g.math('LESS_THAN', owner, 2**20))
    valid = valid*c._stat(g, geometry, fields)
    encoded = g.setpos(geometry, g.xyz(role, kind, owner))
    unique = g.node('GeometryNodeMergeByDistance', 'Free-chain owner permissions must be unique')
    unique.inputs['Distance'].default_value = .1; g.bind(encoded, unique.inputs['Geometry'])
    valid = valid*g.math('COMPARE', c._count(g, geometry), c._count(g, unique.outputs['Geometry']))
    return encoded, valid


def _allowed(g, rules, role, kind, owner):
    requested = g.xyz(role, kind, owner)
    nearest = g.node('GeometryNodeSampleNearest', 'Exact bounded owner tuple, never geometric proximity')
    nearest.domain = 'POINT'; g.bind(rules, nearest.inputs['Geometry'])
    g.bind(requested, nearest.inputs['Sample Position'])
    actual = c._sample(g, rules, g.position(), nearest.outputs['Index'], 'FLOAT_VECTOR')
    distance = g.node('ShaderNodeVectorMath'); distance.operation = 'DISTANCE'
    g.bind(requested, distance.inputs[0]); g.bind(actual, distance.inputs[1])
    return g.math('LESS_THAN', distance.outputs['Value'], .1)


def _free_cap(g, pavement, side_a, side_b, head, ends, cell_size, *, chained=False, variable_heights=False):
    """Construct only the new cap; all other boundary samples are immutable."""
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    a, b = (c._sample(g, pavement, g.position(), at, 'FLOAT_VECTOR') for at in ends)
    axes_a, axes_b = g.separate(a), g.separate(b)
    distance = g.math('SQRT', sum((y-x)**2 for x, y in zip(axes_a, axes_b)))
    desired = 2.*g.math('CEIL', distance/(2.*c.V(g, cell_size)))
    head_intervals = c._count(g, head)-1.
    # Keep the proven unequal-cap chart within its bounded count ratio.
    # Counts start even; a chained free cap may receive one parity sample.
    minimum = 2.*g.math('CEIL', head_intervals/6.)
    maximum = 3.*head_intervals
    intervals = g.math('MAXIMUM', 4., g.math('MINIMUM', maximum, g.math('MAXIMUM', minimum, desired)))
    metrics = {}
    if chained:
        # A quad disk needs an even perimeter. Original side counts are fixed;
        # only the new free cap may gain a sample. The free-cap surface chart
        # transfers its first/last edge to the odd side, leaving even cap counts
        # for the existing direct-quad construction. No pavement edge changes.
        parity = g.math('FLOORED_MODULO', c._count(g, side_a)+c._count(g, side_b)-2., 2.)
        intervals = intervals+parity
        metrics['free_cap_parity'] = parity
    valid = (g.math('GREATER_THAN', cell_size, 0.)*
             g.math('GREATER_THAN', distance, 1e-5)*
             g.math('GREATER_THAN', head_intervals, 3.5)*
             g.math('COMPARE', g.math('FLOORED_MODULO', head_intervals, 2.), 0.)*
             g.math('LESS_THAN', intervals, MAX_CAP_INTERVALS+.5))
    intervals = c.bounded(g, intervals, 4., MAX_CAP_INTERVALS)
    interpolated = g.xyz(*(x+(y-x)*(index/intervals) for x, y in zip(axes_a, axes_b)))
    position = c.choose(g, g.math('COMPARE', index, 0.), a,
                        c.choose(g, g.math('COMPARE', index, intervals), b, interpolated, 'VECTOR'), 'VECTOR')
    tail = g.setpos(c._line(g, intervals+1.), position)
    base_count = c._count(g, pavement)
    identity = c.choose(g, g.math('COMPARE', index, 0.), ends[0],
                       c.choose(g, g.math('COMPARE', index, intervals), ends[1], base_count+index-1.), 'INT')
    tail = c._store(g, tail, 'st_sb_original_vertex', identity, 'INT')
    # Only interior cap vertices are appended. Its endpoint IDs still refer
    # to the two existing carriageway vertices, avoiding duplicate references.
    height = c._sample(g, pavement, c.named(g, 'st_cn_height'), ends[0])
    if variable_heights:
        other_height = c._sample(g, pavement, c.named(g, 'st_cn_height'), ends[1])
        # The new cap interpolates both existing end heights. Its coordinates
        # already use the same convex interpolation; no road edge is moved.
        height = height+(other_height-height)*(index/intervals)
        # Capture on the complete cap before selecting its interior. Selection
        # renumbers vertices, so evaluating Index afterwards shifts the blend.
        tail = c._store(g, tail, 'st_cn_height', height)
        height = c.named(g, 'st_cn_height')
    interior = c._select(g, tail, g.math('GREATER_THAN', index, 0.)*g.math('LESS_THAN', index, intervals))
    interior = c._store(g, interior, 'st_cn_height', height)
    reference = boundary._join(g, pavement, interior)
    metrics.update(tail_intervals=intervals, cap_valid=valid, original_vertices=base_count,
                   reference_vertices=c._count(g, reference))
    return reference, tail, valid, metrics


def build(*, chained=False, crossing_cap=False, selection_caps=False, original_terminal_rows=False):
    if original_terminal_rows and (not chained or crossing_cap):
        raise ValueError('Original free-row ownership requires a complete chained separator')
    if selection_caps and (chained or crossing_cap):
        raise ValueError('Selection caps require two explicitly bounded direct member extents')
    """Free approaches, optionally extended through declared member owners.

    The chained primitive requires its caller to validate original route-chain
    semantics. Owner permissions select existing boundary edges, not arbitrary
    components. Both the exact endpoint topology and complete footprint must
    still pass before the new free cap is accepted.
    """
    if crossing_cap and not chained:
        raise ValueError('A crossing-to-free boundary requires explicit owner permissions')
    name = NAME+' / Chained v1' if chained else NAME
    if crossing_cap: name += ' / Crossing cap candidate'
    if selection_caps:name += ' / Declared selection caps v1'
    if original_terminal_rows:name += ' / Original terminal owner rows v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    if original_terminal_rows:g.g['st_original_terminal_owner_rows']=1
    for name in ('Pavement', 'External Approaches', 'Mouths'):
        g.socket(name, 'NodeSocketGeometry')
    for name in ('Member A', 'Member B', 'Attached Patch'):
        g.socket(name, 'NodeSocketInt')
    if chained:
        g.socket('Allowed Owners', 'NodeSocketGeometry')
        for name in ('A Attached', 'B Attached'): g.socket(name, 'NodeSocketInt')
    if crossing_cap:
        for member in ('A', 'B'):
            for name in ('Inner Side', 'External'):
                g.socket(member+' '+name, 'NodeSocketInt')
    if selection_caps:
        for member in ('A','B'):
            for name in ('End Role','End Section'):g.socket(member+' '+name,'NodeSocketInt',default=-1)
    g.socket('Cell Size', 'NodeSocketFloat', default=1.)
    for name in ('Reference', 'Side A', 'Side B', 'Head', 'Tail', 'Diagnostics'):
        g.socket(name, 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    pavement = c._store(g, inp.outputs['Pavement'], 'st_sb_original_vertex', index, 'INT')
    pavement = g.store(pavement, 'st_sb_original_face', index+1., 'FACE', 'INT')
    for key in ('kind', 'owner'):
        pavement = g.store(pavement, 'st_sb_'+key, c.named(g, 'st_cn_'+key, 'INT'), 'EDGE', 'INT')
    adjacent = g.node('GeometryNodeInputMeshEdgeNeighbors').outputs['Face Count']
    edge = g.node('GeometryNodeInputMeshEdgeVertices')
    # Explicit point samples avoid rounding a point-domain integer to EDGE.
    is_cap = 1.
    for key in ('Vertex Index 1', 'Vertex Index 2'):
        is_cap = is_cap*g.math('COMPARE', c._sample(g, pavement, c.named(g, 'st_cs_end', 'INT'),
                                                  edge.outputs[key], 'INT'), 1.)
    pavement = g.store(pavement, 'st_sb_free_cap', is_cap, 'EDGE', 'BOOLEAN')
    wire = closed._edges(g, pavement, g.math('COMPARE', adjacent, 1.))
    external = inp.outputs['External Approaches']; mouths = inp.outputs['Mouths']
    kind = c.named(g, 'st_sb_kind', 'INT'); owner = c.named(g, 'st_sb_owner', 'INT')
    keys = g.separate(c.named(g, '_bridge_key', 'FLOAT_VECTOR'))
    islands = g.node('GeometryNodeInputMeshIsland')
    neighbor = g.node('GeometryNodeInputMeshVertexNeighbors').outputs['Vertex Count']
    valid = 1.-g.math('COMPARE', inp.outputs['Member A'], inp.outputs['Member B'])
    if original_terminal_rows:
        from .curved_network_ownership_nodes import _compare
        valid = 1.-_compare(g, inp.outputs['Member A'], inp.outputs['Member B'])
    if selection_caps:
        valid*=g.math('MINIMUM',1.,g.math('COMPARE',inp.outputs['A End Role'],6.)+
                      g.math('COMPARE',inp.outputs['B End Role'],6.))
    if chained:
        rules, rules_valid = _permissions(g, inp.outputs['Allowed Owners'])
        valid = valid*rules_valid
        cap_rules = c._select(g, rules, g.math('COMPARE', c.named(g, 'st_sr_role', 'INT'), 2.))
        if crossing_cap:
            # Exact cap incidence is bound from the original source junctions.
            # The geometry still has to form one chain joining both anchors.
            cap_kind = c.named(g, 'st_sr_kind', 'INT')
            valid = (valid*g.math('COMPARE', c._count(g, cap_rules), 3.)*
                g.math('COMPARE', c._stat(g, cap_rules, g.math('COMPARE', cap_kind, 0.), 'Sum'), 2.)*
                g.math('COMPARE', c._stat(g, cap_rules, g.math('COMPARE', cap_kind, 1.), 'Sum'), 1.))
        else:
            valid = valid*g.math('COMPARE', c._count(g, cap_rules), 1.)
            valid = valid*c._stat(g, cap_rules, g.math('COMPARE', c.named(g, 'st_sr_kind', 'INT'), 0.)*
                g.math('COMPARE', c.named(g, 'st_sr_owner', 'INT'), inp.outputs['Attached Patch']))
    pieces = {}; anchors = []; ends = []; metrics = {}
    for side_index, member in enumerate(('A', 'B')):
        if original_terminal_rows:
            # The native semantic registry has already proved every original
            # Street and exact join. The terminal can be a different Street
            # from the attached mouth: use its sole explicit kind-3 grant.
            selected = c._select(g, rules, _compare(g, c.named(g, 'st_sr_role', 'INT'), side_index)*
                                 _compare(g, c.named(g, 'st_sr_kind', 'INT'), 3))
            row = c._read(g, selected, 'st_sr_owner', 0, 'INT')
            found = _compare(g, c._count(g, selected), 1)*_compare(g, row, 0, 'GREATER_EQUAL')*\
                    _compare(g, row, c._count(g, external), 'LESS_THAN')
        else:
            found, row = providers._lookup(g, external, 'st_ca_street_id', inp.outputs['Member '+member])
        role = c._read(g, external, 'st_ca_end_role', row, 'INT')
        terminal_valid=g.math('COMPARE',role,1.)
        if selection_caps:
            from .curved_network_ownership_nodes import _compare
            expected=inp.outputs[member+' End Role'];section=inp.outputs[member+' End Section']
            clipped=_compare(g,expected,6)
            terminal_valid=_compare(g,role,expected)*(_compare(g,expected,1)+clipped)
            terminal_valid*=_compare(g,c._read(g,external,'st_ca_owner_id',row,'INT'),section)
            terminal_valid*=_compare(g,c._read(g,external,'st_ca_next_section_id',row,'INT'),-1)
            terminal_valid*=c.choose(g,clipped,_compare(g,section,0,'GREATER_EQUAL'),_compare(g,section,-1))
        port = c._read(g, external, 'st_ca_start_index', row, 'INT')
        if chained: port = inp.outputs[member+' Attached']
        mouth_found, mouth_row = providers._lookup(g, mouths, 'st_cj_input_index', port)
        half = c._read(g, mouths, 'st_cj_half', mouth_row, 'INT')
        inner_side = c.V(g, inp.outputs[member+' Inner Side']) if crossing_cap else half
        rank = .5*(inner_side+1.)*c._read(g, mouths, 'st_cs_intervals', mouth_row, 'INT')
        profile_valid = g.math('COMPARE', g.math('ABSOLUTE', half), 1.)
        if crossing_cap:
            profile_valid = (g.math('COMPARE', g.math('ABSOLUTE', inner_side), 1.)*
                g.math('MAXIMUM', g.math('COMPARE', half, 0.), g.math('COMPARE', half, inner_side)))
            valid = (valid*g.math('COMPARE', row, inp.outputs[member+' External'])*
                g.math('COMPARE', c._read(g, external, 'st_ca_owner_id', row, 'INT'), -1.)*
                g.math('COMPARE', c._read(g, external, 'st_ca_next_section_id', row, 'INT'), -1.))
        anchor = (g.math('COMPARE', keys[0], 0.)*g.math('COMPARE', keys[1], port)*
                  g.math('COMPARE', keys[2], rank))
        anchors.append(anchor)
        # Once welded to a patch, the remaining approach boundary is a U.
        # Remove its actual free-end row, leaving the two long open sides.
        member_edges = (g.math('COMPARE', kind, 3.)*g.math('COMPARE', owner, row)*
                        (1.-c.named(g, 'st_sb_free_cap', 'BOOLEAN')))
        if chained:
            member_edges = _allowed(g, rules, float(side_index), kind, owner)*(
                1.-g.math('COMPARE', kind, 3.)*c.named(g, 'st_sb_free_cap', 'BOOLEAN'))
        sides = closed._edges(g, wire, member_edges)
        anchor_count = c._stat(g, sides, anchor, 'Sum')
        island = c._stat(g, sides, anchor*c.V(g, islands.outputs['Island Index']), 'Sum')
        side = c._select(g, sides, g.math('COMPARE', islands.outputs['Island Index'], island))
        end = g.math('COMPARE', neighbor, 1.)
        free_end = end*g.math('COMPARE', c.named(g, 'st_cs_end', 'INT'), 1.)
        if chained: free_end = free_end*(1.-anchor)
        free_count = c._stat(g, side, free_end, 'Sum')
        free_id = c._stat(g, side, free_end*c.named(g, 'st_sb_original_vertex', 'INT'), 'Sum')
        chain_valid = _chain_valid(g, side)
        valid = (valid*found*mouth_found*terminal_valid*
                 profile_valid*
                 g.math('COMPARE', anchor_count, 1.)*g.math('COMPARE', free_count, 1.)*
                 g.math('COMPARE', c._stat(g, side, anchor*end, 'Sum'), 1.)*chain_valid)
        if chained:
            # The far endpoint must lie on this member's actual free row.
            # A dangling edge at an undeclared side attachment cannot stand in
            # for the free end, even if it has the same cached row attribute.
            cap = closed._edges(g, wire, g.math('COMPARE', kind, 3.)*
                g.math('COMPARE', owner, row)*c.named(g, 'st_sb_free_cap', 'BOOLEAN'))
            cap_match = c._stat(g, cap, g.math('COMPARE', c.named(g, 'st_sb_original_vertex', 'INT'), free_id), 'Sum')
            valid = valid*g.math('COMPARE', cap_match, 1.)
            metrics[member+'_free_cap_match'] = cap_match
        pieces['Side '+member] = side; ends.append(free_id)
        for key, value in dict(row=row, end_role=role, anchor_count=anchor_count,
                               free_count=free_count, free_vertex=free_id, chain_valid=chain_valid,
                               vertices=c._count(g, side)).items():
            metrics[member+'_'+key] = value
    patch = closed._edges(g, wire, g.math('COMPARE', kind, 0.)*
                          g.math('COMPARE', owner, inp.outputs['Attached Patch']))
    if crossing_cap:
        patch = closed._edges(g, wire, _allowed(g, rules, 2., kind, owner))
    head_island = c._stat(g, patch, anchors[0]*c.V(g, islands.outputs['Island Index']), 'Sum')
    head = c._select(g, patch, g.math('COMPARE', islands.outputs['Island Index'], head_island))
    head_valid = _chain_valid(g, head)
    for member, anchor in zip(('A', 'B'), anchors):
        count = c._stat(g, head, anchor*g.math('COMPARE', neighbor, 1.), 'Sum')
        valid = valid*g.math('COMPARE', count, 1.)
        metrics[member+'_head_anchor_count'] = count
    valid = valid*head_valid
    reference, tail, cap_valid, cap_metrics = _free_cap(
        g, pavement, pieces['Side A'], pieces['Side B'], head, ends, inp.outputs['Cell Size'],
        chained=chained, variable_heights=crossing_cap)
    valid = valid*cap_valid
    footprint = _simple_footprint(g, reference, pieces['Side A'], pieces['Side B'], head, tail)
    valid = valid*footprint
    pieces.update(Reference=reference, Head=head, Tail=tail)
    record = c._line(g, 1)
    metrics.update(head_vertices=c._count(g, head), head_chain_valid=head_valid,
                   footprint_clear=footprint, **cap_metrics)
    for name, value in metrics.items():
        record = c._store(g, record, 'st_sb_'+name, value, 'INT')
    record = c._store(g, record, 'st_sb_valid', valid, 'BOOLEAN')
    for name, geometry in pieces.items():
        g.bind(boundary._empty(g, geometry, valid), out.inputs[name])
    g.bind(record, out.inputs['Diagnostics']); g.bind(valid, out.inputs['Valid'])
    return g.g
